function sv7_report_dir():string{return dirname(__DIR__).DIRECTORY_SEPARATOR.'private'.DIRECTORY_SEPARATOR.'safety-vote'.DIRECTORY_SEPARATOR.'reports';}
function sv7_evidence(array$c):array{$elig=db_row("SELECT * FROM SafetyVote_EligibilitySnapshots WHERE CampaignVersionID=? AND Status='frozen' ORDER BY SnapshotNo DESC LIMIT 1",[$c['CurrentVersionID']]);$voters=$elig?db_rows('SELECT EmployeeID employeeId,DepartmentIDSnapshot departmentId,SafetyUnitIDSnapshot safetyUnitId,PositionIDSnapshot positionId,RoleSnapshot role,TeamSnapshot team,AccountReady accountReady FROM SafetyVote_EligibleVoters WHERE SnapshotID=? ORDER BY EmployeeID',[$elig['id']]):[];$snap=db_row("SELECT * FROM SafetyVote_ResultSnapshots WHERE CampaignVersionID=? AND Status IN ('Certified','Published') ORDER BY SnapshotNo DESC LIMIT 1",[$c['CurrentVersionID']]);$cert=$snap?db_row("SELECT COUNT(DISTINCT CertifierEmployeeID) n FROM SafetyVote_Certifications WHERE ResultSnapshotID=? AND Decision='certified' AND RevokedAt IS NULL AND ResultHashSnapshot=?",[$snap['id'],$snap['ResultHash']]):['n'=>0];$report=$snap?db_row("SELECT * FROM SafetyVote_Reports WHERE ResultSnapshotID=? AND Status='Ready' ORDER BY id DESC LIMIT 1",[$snap['id']]):null;$ident=db_row('SELECT COUNT(*) n FROM SafetyVote_BallotIdentities bi JOIN SafetyVote_Ballots b ON b.id=bi.BallotID WHERE b.CampaignVersionID=?',[$c['CurrentVersionID']]);$actual='';if($report){$file=sv7_report_dir().DIRECTORY_SEPARATOR.basename($report['StoredName']);if(is_file($file))$actual=hash_file('sha256',$file);}return['elig'=>$elig,'snap'=>$snap,'report'=>$report,'activeCertifiers'=>(int)($cert['n']??0),'identityMappings'=>(int)($ident['n']??0),'eligibilityActual'=>$elig?sv2_rows_hash(array_map(fn($x)=>$x+['accountReady'=>(bool)$x['accountReady']],$voters)):'','reportActual'=>$actual];}
function sv7_handoff_input(array$c,string$target):array{$e=sv7_evidence($c);return['targetAdapter'=>$target,'resultStatus'=>$e['snap']['Status']??'','campaignCode'=>$c['CampaignCode'],'resultSnapshotId'=>(int)($e['snap']['id']??0),'resultHash'=>$e['snap']['ResultHash']??'','reportId'=>$e['report']['ReportID']??'','reportSha256'=>$e['report']['ContentSha256']??'','_e'=>$e];}
function handle_safety_vote_phase7_routes(string$method,string$path):bool{if(strpos($path,'/safety-vote/')!==0)return false;$catalog=$path==='/safety-vote/admin/integrations/catalog';$providers=$path==='/safety-vote/admin/integrations/providers';$employees=$path==='/safety-vote/admin/integrations/system-control/employees';$verify=route_params($path,'/safety-vote/admin/campaigns/:id/release-verification');$preview=route_params($path,'/safety-vote/admin/campaigns/:id/integrations/handoffs/preview');$confirm=route_params($path,'/safety-vote/admin/campaigns/:id/integrations/handoffs/confirm');$accept=route_params($path,'/safety-vote/admin/campaigns/:id/acceptance-evidence');$observe=route_params($path,'/safety-vote/admin/campaigns/:id/observability');$preflight=route_params($path,'/safety-vote/admin/campaigns/:id/release-preflight');if(!$catalog&&!$providers&&!$employees&&!$verify&&!$preview&&!$confirm&&!$accept&&!$observe&&!$preflight)return false;$u=require_user();$required=['SafetyVote_IntegrationSnapshots','SafetyVote_IntegrationHandoffs','SafetyVote_AcceptanceEvidence','SafetyVote_OperationalAlerts'];$marks=implode(',',array_fill(0,count($required),'?'));$found=db_rows("SELECT TABLE_NAME FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ($marks)",$required);$v=db_row("SELECT SettingValue FROM SafetyVote_Settings WHERE SettingKey='schema_version'");if(count($found)!==count($required)||($v['SettingValue']??'')!=='2026-10-08-phase7-r1')json_response(['success'=>false,'code'=>'SAFETY_VOTE_PHASE7_SCHEMA_NOT_READY'],503);
 if($catalog&&$method==='GET'){sv_require_permission($u,'SAFETY_VOTE_MANAGE');json_response(['success'=>true,'data'=>['contract'=>SV7_CONTRACT,'adapters'=>sv7_catalog()]]);}
 if($providers&&$method==='GET'){sv_require_permission($u,'SAFETY_VOTE_MANAGE');json_response(['success'=>true,'data'=>['adapterMode'=>getenv('SAFETY_VOTE_PHASE7_ADAPTER_MODE')==='fixture'?'fixture':'unconfigured','calendar'=>['mode'=>'read_only','externalMutation'=>false],'notification'=>['mode'=>'read_only','externalMutation'=>false],'certifiedResult'=>['explicitConfirmation'=>true,'dualCertificationRequired'=>true]]]);}
 if($employees&&$method==='GET'){sv_require_permission($u,'SAFETY_VOTE_MANAGE');$q='%'.substr(trim((string)($_GET['q']??'')),0,80).'%';$rows=db_rows("SELECT EmployeeID employeeId,EmployeeName employeeName,Department department,Unit unit,Team team,Position position,Role role FROM Employees WHERE (?='%%' OR EmployeeID LIKE ? OR EmployeeName LIKE ?) ORDER BY EmployeeID LIMIT 100",[$q,$q,$q]);json_response(['success'=>true,'data'=>['source'=>'system_control_hr_master','mode'=>'read_only','snapshotHash'=>sv7_hash($rows),'rows'=>$rows]]);}
