 if($preview&&$method==='POST'){sv_require_permission($u,'SAFETY_VOTE_EXPORT');$c=sv7_campaign((int)$preview['id']);if(!$c)json_response(['success'=>false,'code'=>'CAMPAIGN_NOT_FOUND'],404);$in=sv7_handoff_input($c,(string)(json_body()['targetAdapter']??''));$out=sv7_preview($in);if(!$out['ok']||$in['_e']['activeCertifiers']<2||$in['_e']['identityMappings'])json_response(['success'=>false,'code'=>'HANDOFF_PRECONDITION_FAILED','details'=>$out['errors']],422);json_response(['success'=>true,'data'=>$out+['externalMutation'=>false]]);}
 if($confirm&&$method==='POST'){sv_require_permission($u,'SAFETY_VOTE_CERTIFY');if(getenv('SAFETY_VOTE_PHASE7_ADAPTER_MODE')!=='fixture')json_response(['success'=>false,'code'=>'INTEGRATION_ADAPTER_UNAVAILABLE'],503);$c=sv7_campaign((int)$confirm['id']);if(!$c)json_response(['success'=>false,'code'=>'CAMPAIGN_NOT_FOUND'],404);$b=json_body();$in=sv7_handoff_input($c,(string)($b['targetAdapter']??''));$out=sv7_confirm($in+['confirmation'=>$b['confirmation']??'','previewHash'=>$b['previewHash']??'']);$e=$in['_e'];if(!$out['ok']||$e['activeCertifiers']<2||$e['identityMappings']||$e['reportActual']!==($e['report']['ContentSha256']??''))json_response(['success'=>false,'code'=>'HANDOFF_PRECONDITION_FAILED','details'=>$out['errors']],422);$receipt='FIXTURE-'.strtoupper(substr($out['previewHash'],0,16));try{db_execute("INSERT INTO SafetyVote_IntegrationHandoffs(CampaignID,CampaignVersionID,ResultSnapshotID,ReportID,TargetAdapter,PreviewHash,ResultHash,ReportSha256,Status,ConfirmationHash,ProviderReceipt,RequestedBy,ConfirmedBy,ConfirmedAt,MetadataJson) VALUES(?,?,?,?,?,?,?,?,'Delivered',?,?,?,?,NOW(),?)",[$c['id'],$c['CurrentVersionID'],$e['snap']['id'],$e['report']['id'],$out['payload']['targetAdapter'],$out['previewHash'],$out['payload']['resultHash'],$out['payload']['reportSha256'],sv7_hash($out['confirmation']),$receipt,sv_actor($u),sv_actor($u),json_encode(sv7_safe_metadata(['targetAdapter'=>$out['payload']['targetAdapter'],'previewHash'=>$out['previewHash'],'resultHash'=>$out['payload']['resultHash'],'reportId'=>$out['payload']['reportId'],'reportSha256'=>$out['payload']['reportSha256'],'providerReceipt'=>$receipt]))]);json_response(['success'=>true,'data'=>['id'=>(int)db()->lastInsertId(),'status'=>'Delivered','providerReceipt'=>$receipt,'externalDelivery'=>false,'payload'=>$out['payload']]],201);}catch(Throwable$e){json_response(['success'=>false,'code'=>'HANDOFF_ALREADY_CONFIRMED'],409);}}
 if($accept&&$method==='GET'){sv_require_permission($u,'SAFETY_VOTE_AUDIT_VIEW');$rows=db_rows('SELECT AcceptanceArea acceptanceArea,Decision decision,EvidenceReference evidenceReference,EvidenceSha256 evidenceSha256,ApprovedBy approvedBy,ApprovedAt approvedAt,ExpiresAt expiresAt,RevokedAt revokedAt FROM SafetyVote_AcceptanceEvidence WHERE CampaignID=? ORDER BY id',[(int)$accept['id']]);json_response(['success'=>true,'data'=>['required'=>SV7_ACCEPTANCE,'rows'=>$rows]]);}
