 if($preflight&&$method==='GET'){sv_require_permission($u,'SAFETY_VOTE_ADMIN');$c=sv7_campaign((int)$preflight['id']);if(!$c)json_response(['success'=>false,'code'=>'CAMPAIGN_NOT_FOUND'],404);$e=sv7_evidence($c);$acc=array_map(fn($x)=>$x['area'],db_rows("SELECT DISTINCT AcceptanceArea area FROM SafetyVote_AcceptanceEvidence WHERE CampaignID=? AND Decision='Accepted' AND RevokedAt IS NULL AND (ExpiresAt IS NULL OR ExpiresAt>NOW())",[$c['id']]));$fixture=getenv('SAFETY_VOTE_PHASE7_EVIDENCE_MODE')==='fixture_pass';$out=sv7_preflight(['campaignType'=>$c['CampaignType']??'','privacyMode'=>$c['PrivacyMode']??'','schemaReady'=>true,'fixtureOnly'=>getenv('SAFETY_VOTE_PHASE7_ADAPTER_MODE')==='fixture','identityMappings'=>$e['identityMappings'],'activeCertifiers'=>$e['activeCertifiers'],'resultHashVerified'=>!empty($e['snap']['ResultHash']),'reportHashVerified'=>!empty($e['report'])&&$e['reportActual']===$e['report']['ContentSha256'],'backupRestorePassed'=>$fixture,'accessibilityPassed'=>$fixture,'performancePassed'=>$fixture,'loadPassed'=>$fixture,'permissionMatrixReviewed'=>$fixture,'immutableSource'=>false,'acceptanceAreas'=>$acc]);json_response(['success'=>true,'data'=>$out+['productionConnected'=>false,'deployAuthorized'=>false]]);}
